# No receiver, RF access, or runtime configuration changes.
# Arch-aware: the x86_64 and aarch64 command lines below are deliberately DUPLICATED, not factored
# into shared variables. Byte-identity with the original x86 script and with the DGX
# offline_sync_arm.sh (incl. its doubled -mcpu=native) beats DRY.
ARCH=$(uname -m)
cd ${REPO}/cmake_targets/ran_build/build
if [ "$ARCH" = "aarch64" ]; then
CPM_INC=$(find ~/.cache/cpm -path '*googletest/include' 2>/dev/null | head -1)
